"""Byte-to-text contracts checked against the complete pinned source."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='바이너리 표현 · 비트 스트림 · 버퍼 계약',
                     sections=sections, questions=questions))


add('lib/hexdump.c', '16진 변환과 덤프 전체: 경계 검사·정렬·로그 출력',
    '숫자 한 자리 변환에서 바이너리 덤프 로그까지 단계적으로 구성한 구현입니다.',
    'hex_to_bin은 산술 마스크로 문자 범위를 분류하고, hex2bin은 두 니블을 결합합니다. 덤프는 한 줄 포맷과 여러 줄 로그 출력을 분리합니다.',
    '변환 길이와 버퍼 용량, 실패 전 출력 변경을 구분합니다. 바이트 묶음 덤프는 CPU의 정수 표현을 사용하므로 바이트별 출력과 순서가 달라질 수 있습니다.',
    [('전체 구성', 'SPDX와 의존 헤더 뒤에 소문자·대문자 문자표와 export가 있습니다. hex_to_bin, hex2bin, bin2hex, hex_dump_to_buffer를 정의·export하고 CONFIG_PRINTK 조건 안에서 print_hex_dump를 정의·export합니다. 설정에 따라 마지막 함수의 빌드 여부가 달라집니다.'),
     ('분기 없는 한 자리 변환', 'hex_to_bin은 unsigned char 입력에 대해 0..9와 A..F 범위를 각각 산술식으로 표시합니다. ch&0xdf로 소문자를 대문자 영역에 맞춥니다. 범위 안일 때만 숫자에 1을 더한 값 또는 알파벳에 11을 더한 값이 살아남고 처음의 -1과 합쳐 0..15가 됩니다. 어느 범위에도 없으면 -1입니다. 음수 오른쪽 이동에 의존하지 않도록 unsigned 변환 후 >>8을 수행합니다.'),
     ('부채널과 검증 범위', '주석은 암호 키 입력에도 사용하므로 데이터에 의존하는 조건문이나 메모리 접근을 없애려는 의도를 설명합니다. 소스에 조건문이 없다는 사실만으로 모든 컴파일러·CPU에서 일정 시간이 증명되는 것은 아닙니다. 또한 이어지는 hex2bin은 유효성에 따라 즉시 반환하므로 전체 문자열 변환까지 같은 성질이라고 일반화할 수 없습니다.'),
     ('두 자리 결합과 실패', 'hex2bin의 count는 출력 바이트 수입니다. 매번 상위·하위 문자를 읽고 각각 hex_to_bin 결과가 음수인지 검사한 뒤 (hi<<4)|lo를 씁니다. count0은 아무것도 읽거나 쓰지 않고 성공합니다. 잘못된 문자가 나오면 -EINVAL이며 앞에서 성공한 바이트는 이미 써졌습니다. 원문 길이 인자가 없으므로 읽을 수 있는 2*count개 문자를 호출자가 보장해야 합니다.'),
     ('반대 방향의 연속 쓰기', 'bin2hex는 unsigned char 포인터로 원문을 순회하며 hex_byte_pack이 반환한 다음 위치를 dst로 삼습니다. 반환값은 시작 주소가 아니라 마지막 글자 뒤 위치입니다. 2*count개 소문자 글자를 쓰며 NUL 종료는 하지 않습니다.'),
     ('한 줄 입력 정규화', 'hex_dump_to_buffer는 rowsize가 16 또는 32가 아니면 16으로 바꾸고 len을 rowsize 이하로 제한합니다. groupsize는 1,2,4,8을 사용하며 유효한 2의 거듭제곱이 아니거나 8보다 크면 1로 바꿉니다. len이 groupsize로 나누어떨어지지 않아도 1로 바꿔 한 줄에 서로 다른 그룹 크기를 섞지 않습니다.'),
     ('묶음 출력과 엔디언', '8/4/2바이트 묶음은 get_unaligned로 정수를 읽고 각각 16/8/4자리 16진수로 출력합니다. 비정렬 읽기 지원과 엔디언 변환은 별개입니다. 예를 들어 little-endian에서 바이트 01 02를 2바이트 묶음으로 읽으면 0201로 표시됩니다. groupsize1은 각 바이트의 상위·하위 니블을 출력하므로 01 02가 됩니다.'),
     ('ASCII 열과 종료', 'ASCII 시작 열은 rowsize*2+rowsize/groupsize+1입니다. 필요하면 공백을 채운 뒤 원래 각 바이트가 ASCII이고 출력 가능한 경우만 그대로 쓰고 나머지는 점으로 표시합니다. 정상 종료 nil은 linebuf[lx]에 NUL을 씁니다. len0이고 용량이 양수라면 빈 문자열과 반환값 0입니다.'),
     ('용량 부족과 반환값', '그룹 출력은 snprintf의 필요한 길이를 보고 잘림을 감지합니다. 바이트·공백·ASCII 경로는 NUL 한 칸을 남겨 검사하며 overflow2에서 종료 문자를 씁니다. overflow1은 ascii면 ascii_column+len, 아니면 (groupsize*2+1)*ngroups-1을 반환합니다. 용량0이면 아무것도 쓰지 않고 바로 이 계산으로 갑니다. 따라서 len0·용량0·ascii=false는 -1이며, ascii=true는 열 위치 값입니다. 이 특수 경로를 모든 입력에서 단순한 실제 문자열 길이라고 해석하면 안 됩니다.'),
     ('여러 줄 로그 출력', 'CONFIG_PRINTK의 print_hex_dump는 최대 32바이트의 hex+ASCII와 NUL을 담는 지역 버퍼를 사용합니다. rowsize를 정규화하고 원문을 줄 단위로 잘라 포맷합니다. prefix_type에 따라 %p 주소, 8자리 이상으로 표시하는 16진 오프셋, 또는 추가 접두사 없는 경로를 고릅니다. level과 prefix_str도 함께 printk에 전달합니다. 커널 %p 정책을 무시하고 항상 원시 주소가 출력된다고 가정하면 안 됩니다.'),
     ('CS 연결과 한계', '니블 결합, 산술 범위 검사, 데이터 의존 제어 흐름, 용량과 필요 길이, 정렬과 엔디언, 포맷과 출력 장치의 분리를 학습합니다. len은 size_t지만 로그 루프의 i와 remaining은 int여서 임의의 거대한 입력까지 안전하다고 주장하지 않습니다. 이 수업의 전체 분기 해설은 원본 대조에 근거하며 실제 printk나 모든 아키텍처의 실행 검증은 아닙니다.')],
    [('hex2bin에서 두 번째 출력 바이트의 문자가 잘못되면 첫 번째 바이트는?', '이미 출력 버퍼에 써졌을 수 있다', '반드시 원래 값으로 복구된다', '검사와 저장은 한 바이트씩 반복합니다. 실패 시 이전 저장을 되돌리는 경로는 없습니다.'),
     ('len6, groupsize4를 덤프하면 그룹 크기는?', '1로 바뀐다', '4바이트 그룹 하나와 2바이트 그룹 하나를 섞는다', 'len%groupsize가 0이 아니면 groupsize=1로 바꿉니다. 혼합 크기 출력을 피하는 분기입니다.'),
     ('little-endian에서 01 02를 groupsize2로 표시하면?', '0201이다', '항상 0102다', 'get_unaligned는 해당 바이트를 CPU 정수로 읽습니다. little-endian의 값은 0x0201이며 그 정수를 네 자리로 표시합니다.'),
     ('linebuflen이 0이면 NUL을 쓸 수 있는가?', '없다. 저장 없이 overflow1로 간다', '가능하다. 항상 linebuf[0]에 쓴다', '용량0은 첫 검사에서 별도 경로로 이동합니다. NUL 종료 설명은 실제로 쓸 수 있는 버퍼가 있을 때와 구분해야 합니다.'),
     ('hex_to_bin의 분기 없는 소스가 hex2bin 전체의 일정 시간을 증명하는가?', '아니다. hex2bin에는 오류에 따른 조기 반환이 있다', '그렇다. 한 자리 함수가 분기 없으면 호출자도 동일하다', '호출자는 각 니블의 음수 결과에 따라 중단합니다. 부채널 성질은 전체 호출 경로와 컴파일된 코드까지 고려해야 합니다.')])


add('lib/base64.c', 'Base64 전체 구현: 비트 누적, 패딩, 느슨한 디코딩',
    '8비트 바이트를 6비트 문자로 변환하고 되돌리는 구현입니다. 정상 형식 생성과 엄격한 입력 검증은 구분해야 합니다.',
    '32비트 누적값 ac와 아직 소비하지 않은 bits를 유지합니다. 인코더는 6비트씩 표를 조회하고 디코더는 8비트씩 출력합니다.',
    '출력 용량 인자가 없으므로 호출자가 충분한 버퍼를 확보해야 합니다. 인코딩은 암호화가 아니며 오류 반환 시 디코딩 출력이 그대로 보존된다고 가정하면 안 됩니다.',
    [('파일 전체 구성', 'GPL SPDX, 작성자와 fs/crypto/fname.c 유래 설명, kernel/types/export/string/base64 헤더 포함, 65칸 문자표, encode와 decode 및 각각의 GPL export로 구성됩니다. 표는 A..Z, a..z, 0..9, +, /의 64문자와 NUL을 담습니다. URL-safe 표의 -와 _를 사용하지 않습니다.'),
     ('인코더의 불변식', '바이트를 읽을 때 ac를 8비트 왼쪽으로 밀어 새 바이트를 OR하고 bits에 8을 더합니다. do-while에서 bits를 6 줄인 뒤 (ac >> bits)&0x3f로 문자를 출력합니다. 각 입력 처리 후 남은 유효 비트는 0, 2, 4개 중 하나입니다. u32에서 오래된 상위 비트가 사라져도 이후에 필요한 하위 비트는 유지됩니다.'),
     ('마지막 문자와 패딩', '남은 비트가 있으면 6비트 칸의 위쪽으로 옮겨 마지막 문자를 쓰고 bits에서 6을 뺍니다. bits가 음수인 동안 =를 쓰며 2씩 올립니다. 입력 1바이트는 ==, 2바이트는 =, 3의 배수는 패딩이 없습니다. 예를 들어 f의 01100110은 011001과 100000으로 나뉘어 Zg==가 됩니다.'),
     ('길이와 버퍼 계약', '정상 비음수 입력 n바이트의 패딩 포함 출력은 4*ceil(n/3)바이트입니다. 반환은 cp-dst이며 NUL을 추가하지 않습니다. 문자열 함수로 후속 처리하려면 호출자가 별도 공간과 종료 문자를 관리해야 합니다. int 길이와 포인터 차이의 표현 범위를 지켜야 하며 임의의 큰 n에 곱셈 공식을 적용할 때도 오버플로 검사가 필요합니다.'),
     ('디코더의 일반 문자 경로', '각 문자를 strchr로 표에서 찾아 인덱스를 6비트 값으로 사용합니다. bits가 8 이상이 되면 8을 빼고 누적값을 오른쪽으로 이동해 바이트를 씁니다. NUL은 strchr가 표 끝을 찾을 수 있어서 src[i]==0 조건으로 별도 거부합니다. 공백이나 개행, -와 _도 표에 없어 거부합니다. srclen을 받으므로 입력 NUL 종료는 필요하지 않습니다.'),
     ('= 처리와 엄격성의 한계', '=는 ac를 6비트 이동하고 bits를 늘린 뒤 필요하면 8을 빼지만 바이트를 출력하지 않습니다. 패딩 위치·개수·전체 길이의 배수 조건을 별도로 검사하지 않습니다. 그래서 ====는 길이 0, A도 길이 0으로 성공하며 Zg는 f로 성공합니다. Zg==A 역시 f로 성공합니다. 함수 설명의 유효성 표현만 보고 정규 형태까지 엄격히 검사한다고 결론 내리면 안 됩니다.'),
     ('남은 비트와 실패 시 상태', '루프 끝에서 ac의 하위 bits개 비트가 0이 아니면 -1입니다. Zg는 남은 4비트가 0이지만 Zh는 1이므로 실패합니다. 바이트는 처리 중 바로 출력하므로 Zm9v!는 foo를 쓴 뒤 !에서 실패합니다. 호출자는 -1이면 반환된 버퍼를 성공 결과로 사용하지 않아야 합니다.'),
     ('CS와 검증', '비트 스트림의 단위 변환, 고정 알파벳 인덱스, 패딩과 문법 검증, 실패 원자성을 연결합니다. 표 크기가 고정되어 strchr를 써도 입력 길이에 대해 선형 시간이지만 매 문자 탐색 비용이 있습니다. check_base64.py는 Python 표준 인코더와 520개 입력을 비교하고 비정규 입력·부분 출력까지 총 3,132개 검사를 수행합니다. 실제 커널 전체 빌드 검증은 아닙니다.')],
    [('한 바이트 f를 인코딩할 때 필요한 출력 공간은?', '패딩 포함 4바이트이며 NUL 공간은 별도다', '2바이트면 패딩과 NUL까지 충분하다', '6비트 데이터 문자는 Zg 두 개지만 구현은 ==도 씁니다. 반환 길이는 4이고 종료 NUL은 쓰지 않습니다.'),
     ('base64_decode가 ====를 거부하는가?', '아니다. 이 구현은 출력 길이 0으로 성공한다', '그렇다. 패딩 위치를 엄격하게 검사한다', '= 분기는 값을 출력하지 않고 비트 상태만 이동합니다. 끝의 남은 비트가 0이면 성공하며 별도 패딩 문법 검사가 없습니다.'),
     ('Zm9v!를 디코딩하면 출력은 보존되는가?', '아니다. foo를 쓴 뒤 -1을 반환한다', '그렇다. 전체 검증 뒤에만 출력한다', '각 8비트가 준비되면 즉시 저장합니다. !가 표에 없어 실패할 때 이미 앞부분이 수정되어 있습니다.'),
     ('입력 속 NUL을 별도로 검사하는 이유는?', 'strchr가 문자표의 종료 NUL 위치를 찾을 수 있기 때문이다', 'NUL은 정상 Base64 알파벳이기 때문이다', '표 배열에는 문자열 종료용 NUL이 있으므로 p가 NULL인지 확인하는 것만으로는 입력 NUL을 거부할 수 없습니다.')])

add('include/linux/base64.h', 'Base64 헤더 전체: 길이 매크로와 구현의 차이',
    '두 변환 함수의 선언과 BASE64_CHARS 계산식을 제공합니다.',
    'BASE64_CHARS(nbytes)는 ceil(4*nbytes/3)을 계산합니다. lib/base64.c의 패딩 포함 출력 크기와 항상 같지는 않습니다.',
    '매크로 이름만 보고 인코더 출력 버퍼를 할당하면 안 됩니다. 비음수 길이 n에 대해 패딩 포함 크기는 4*ceil(n/3)이며 종료 문자와 산술 범위도 따로 고려합니다.',
    [('전체 파일 구성', 'GPL SPDX와 fs/crypto/fname.c 유래 주석, _LINUX_BASE64_H guard, linux/types.h 포함, BASE64_CHARS 매크로, encode/decode 선언 두 개와 endif가 전부입니다. DIV_ROUND_UP 정의를 이 파일 안에 직접 제공하지 않으므로 해당 정의가 보이는 포함 문맥이 필요합니다.'),
     ('두 길이 식 비교', '매크로는 DIV_ROUND_UP((nbytes)*4,3)입니다. n=1이면 2, n=2이면 3, n=3이면 4입니다. 하지만 구현의 출력은 이 세 경우 모두 4바이트입니다. 6비트 표현에 필요한 문자 수와 4문자 묶음에 맞춘 패딩 포함 길이를 구분해야 합니다.'),
     ('타입과 용량', 'encode는 const u8 * 입력과 char * 출력을, decode는 const char * 입력과 u8 * 출력을 받습니다. 둘 다 int len과 int 반환형을 쓰고 출력 용량 인자가 없습니다. 타입만으로 버퍼 충분성이나 길이 비음수 조건을 보장하지 않습니다. (nbytes)*4의 타입별 오버플로에도 주의합니다.'),
     ('CS 연결', '선언과 구현의 계약 대조, 단위 환산과 올림 위치, 텍스트와 바이너리 포인터, API의 누락된 용량 정보를 학습합니다. 헤더의 간단한 크기 식도 실제 호출 대상의 패딩 정책과 맞춰 검토해야 합니다.')],
    [('BASE64_CHARS(2)와 인코더의 실제 출력 길이는?', '각각 3과 4다', '둘 다 3이다', '매크로는 ceil(8/3)=3입니다. 인코더는 데이터 문자 세 개 뒤에 = 하나를 추가합니다.'),
     ('출력 용량이 부족하면 함수가 용량 인자로 감지할 수 있는가?', '아니다. 용량 인자가 없으므로 호출자가 확보해야 한다', '그렇다. len은 출력 용량이다', 'len은 입력 길이입니다. 출력 포인터만 전달되므로 필요한 저장 공간을 호출 전에 계산해야 합니다.')])

add('include/linux/hex.h', 'Hex 헤더 전체: 니블 분해와 연속 버퍼 작성',
    '바이트를 두 자리 16진 문자로 쓰는 inline과 문자열·바이트 변환 선언을 제공합니다.',
    '한 바이트를 상위·하위 4비트로 나누어 문자표를 조회합니다. pack 함수는 두 글자를 쓰고 다음 쓰기 위치를 반환합니다.',
    '호출자는 두 글자 공간을 확보하고 NUL 종료가 필요하면 별도로 처리합니다. hex2bin의 count는 출력할 바이트 수이며 필요한 원문은 두 배 길이입니다.',
    [('파일 전체 구성', 'SPDX, _LINUX_HEX_H guard, types 포함으로 시작합니다. 소문자 표와 두 매크로·pack 함수, 대문자 버전, hex_to_bin/hex2bin/bin2hex 선언, mac_pton 선언과 endif로 구성됩니다. 표와 외부 함수 구현은 이 헤더에 없습니다.'),
     ('니블 추출', 'lo는 x&0x0f이고 hi는 (x&0xf0)>>4입니다. 각 인덱스는 0..15로 제한됩니다. 예를 들어 0xab는 상위 인덱스 10과 하위 11이어서 소문자 표에서는 ab, 대문자 표에서는 AB가 됩니다. 넓은 정수를 매크로에 넣어도 이 두 매크로는 하위 한 바이트의 니블만 사용합니다.'),
     ('pack의 포인터 계약', 'hex_byte_pack과 upper 버전은 상위 글자, 하위 글자 순으로 *buf++에 저장하고 증가한 포인터를 반환합니다. 반환 위치를 다음 pack에 전달해 연속 문자열을 만들 수 있습니다. NUL은 쓰지 않으며 원래 시작 주소를 유지하려면 호출자가 별도로 보관해야 합니다.'),
     ('외부 선언의 역할', 'hex_to_bin은 한 문자를 숫자로 바꾸는 int 결과를, hex2bin은 dst/src/count와 __must_check int 결과를, bin2hex는 출력 포인터를 제공합니다. 실제 실패 조건과 부분 출력은 구현을 읽어 확인해야 합니다. mac_pton은 문자열에서 MAC 바이트 배열로 변환하는 bool API 선언입니다. 이 헤더만으로 입력 버퍼 길이를 보장하지 않습니다.'),
     ('CS 연결', '마스킹과 이동, lookup table, 인덱스 범위, 포인터를 다음 위치로 반환하는 버퍼 작성 관용구를 연결합니다. 문자 표현의 상위 니블 우선 순서는 다중 바이트 정수의 CPU 메모리 엔디언과 별개입니다.')],
    [('hex_byte_pack에 0xab를 전달하면 무엇을 쓰는가?', 'a와 b를 쓰고 두 칸 뒤 포인터를 반환한다', 'b와 a 및 종료 NUL을 쓰고 시작 포인터를 반환한다', '상위 니블을 먼저 저장하고 하위 니블을 저장합니다. 두 번의 후위 증가 후 buf를 반환하며 NUL 저장은 없습니다.'),
     ('16진 두 자리의 상위 니블 우선 출력은 CPU 엔디언에 따라 바뀌는가?', '아니다. 이 함수의 마스크와 출력 순서로 고정된다', '그렇다. little-endian이면 하위 니블부터 출력한다', '함수는 u8 값 하나에 산술 마스크를 적용합니다. 여러 바이트 정수가 메모리에 저장되는 순서와는 다른 문제입니다.')])
